+
+    public int getThreadCount() {
+        return threadCount;
+    }
+
+    public String getLocation() {
+        return location;
+    }
+
+    public Stream getStream() {
+        switch (setting) {
+            case SETTING_AUDIO:
+                return audioStream;
+            case SETTING_VIDEO:
+                return videoStream;
+            case SETTING_SUBTITLES:
+                return subtitlesStream;
+            default:
+                return null;
+        }
+    }
